+            return delegate.engineDecapsulate(encapsulation, from, to,
+                    algorithm);
+        }
+        public int secretSize() {
+            return delegate.engineSecretSize();
+        }
+        public int encapsulationSize() {
+            return delegate.engineEncapsulationSize();
+        }
+    }
